from pathlib import Path
import json,html
out=Path('docs/akaunting')
sources=[
('Product features','https://akaunting.com/features'),('Documentation index','https://akaunting.com/hc/docs/'),('Creating an invoice','https://akaunting.com/hc/docs/invoices-and-estimates/creating-an-invoice/'),('Invoice payments','https://akaunting.com/hc/docs/invoices-and-estimates/adding-payment-to-an-invoice/'),('Creating a bill','https://akaunting.com/hc/docs/bills/creating-a-bill/'),('Bill payments','https://akaunting.com/hc/docs/bills/adding-payment-to-a-bill/'),('Bank transactions','https://akaunting.com/hc/docs/banking-feeds-reconciliations/transactions/'),('Bank feeds','https://akaunting.com/hc/docs/banking-feeds-reconciliations/bank-feeds/'),('Chart of accounts','https://akaunting.com/hc/docs/double-entry-accounting/creating-a-chart-of-accounts/'),('Double-Entry app','https://akaunting.com/apps/double-entry'),('Cash versus accrual','https://akaunting.com/hc/docs/frequently-asked-questions/accrual-vs-cash/'),('Reports catalogue','https://akaunting.com/hc/docs/reports/'),('Roles and permissions','https://akaunting.com/hc/docs/users-and-roles/roles-and-permission-levels/'),('Tax rates','https://akaunting.com/hc/docs/taxes-and-filing/adding-a-new-tax-rate/'),('Products and services','https://akaunting.com/hc/docs/inventory-management/adding-items/'),('Inventory app','https://akaunting.com/apps/inventory'),('Apps and integrations','https://akaunting.com/hc/docs/apps-and-integrations/what-are-apps/'),('Cloud versus self-hosted','https://akaunting.com/hc/docs/frequently-asked-questions/on-premise-vs-cloud/'),('Cloud sign-in','https://app.akaunting.com/auth/login')]
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def bullets(items):return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def box(text):return '<div class="note">'+text+'</div>'
def refs(ids):return '<p class="refs">Sources: '+', '.join('<a href="'+sources[i-1][1]+'">['+str(i)+'] '+sources[i-1][0]+'</a>' for i in ids)+'</p>'
def tree(name,root,branches):
 colors=['#6554cc','#168782','#c47b23','#3974ba','#9a5686','#5a8252','#557184'];height=805;svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 805" role="img" aria-label="'+name+'"><rect width="700" height="805" fill="#ffffff"/>']
 def node(x,y,w,h,text,color,fill='#f7f8fc'):
  svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="{fill}" stroke="{color}" stroke-width="1.4"/>')
  lines=text.split('|');start=y+h/2-(len(lines)-1)*9
  for i,line in enumerate(lines):svg.append(f'<text x="{x+w/2}" y="{start+i*18}" dominant-baseline="middle" text-anchor="middle" fill="{color}" font-family="Arial" font-size="13">{html.escape(line)}</text>')
 node(2,366,125,66,root,'#fff','#252c46')
 for i,(title,leaves) in enumerate(branches):
  y=16+i*111;cy=y+43;c=colors[i]
  svg.append(f'<path d="M127 399 C148 399 145 {cy} 170 {cy}" fill="none" stroke="{c}" stroke-width="1.5"/>');node(170,y+17,151,53,title,c)
  for j,leaf in enumerate(leaves):
   ly=y+j*30
   svg.append(f'<path d="M321 {cy} C340 {cy} 340 {ly+13} 356 {ly+13}" fill="none" stroke="{c}" stroke-width="1.2"/>');node(356,ly,340,26,leaf,c)
 svg.append('</svg>');return ''.join(svg)
feature=tree('Akaunting feature tree','AKAUNTING|Business accounts',[
('Company & access',['Company profile / currency / defaults','Users and permitted companies','Roles and accountant access']),('Sales',['Customers and product/service items','Invoices, discounts and taxes','Receipts, partial payments and portal']),('Purchases',['Vendors and supplier bills','Expense payments and attachments','Recurring bills / unpaid balances']),('Banking',['Cash and bank accounts','Income / expense / transfers','Bank feeds app and reconciliation']),('Accounting apps',['Chart of accounts and journals [A]','Ledger and trial balance [A]','Balance sheet and other statements [A]']),('Reports',['Income, expenses and tax summaries','Cash / accrual reporting basis','Customer and business performance']),('Extensions',['Inventory, payroll and projects [A]','CRM, estimates and expense claims [A]','Payment and third-party integrations [A]'])])
workflow=tree('Accounting workflow tree','COMPANY|Accounting cycle',[
('1. Configure',['Choose company, currency and dates','Set tax rules, accounts and roles','Add customers, vendors and items']),('2. Sell',['Create customer invoice','Receive / match full or partial payment','Track remaining customer balance']),('3. Purchase',['Create supplier bill or expense','Record / match supplier payment','Track remaining amount payable']),('4. Verify cash',['Record the correct bank / cash account','Match imported transactions once','Reconcile records against statements']),('5. Post ledger [A]',['Map income, expense and tax accounts','Check journals and account balances','Review adjustments with accountant']),('6. Review results',['Check income, expenses and taxes','Review receivables and payables','Use ledger statements if app enabled']),('7. Repeat & control',['Resolve discrepancies and missing proof','Review access, exports and backups','Repeat for next reporting period'])])
(out/'feature-tree.svg').write_text(feature,encoding='utf-8');(out/'accounting-workflow-tree.svg').write_text(workflow,encoding='utf-8')
pages=[]
def page(title,body,kicker='PRODUCT & WORKFLOW GUIDE'):pages.append({'title':title,'body':body,'kicker':kicker})
page('Akaunting', '<div class="cover-title">Software overview &amp;<br>accounting workflow</div><p class="lead">A practical guide to the modules, everyday transactions, reports and optional accounting apps.</p><div class="cover-tags">FEATURE TREE &nbsp; / &nbsp; ACCOUNTING TREE &nbsp; / &nbsp; WORKED EXAMPLES</div><div class="cover-bottom"><strong>Prepared for Judibas product discussion</strong><p>Research checked: 20 October 2026<br>PDF guide + editable Word document</p></div>'+box('Based on public official documentation. The private contents, installed apps and subscription of your Akaunting account have not been inspected. This is an independent guide, not an official Akaunting manual.'),'BUSINESS SOFTWARE REFERENCE')
page('01 / What the software does', '<p>Akaunting brings customer billing, supplier costs, money movements and financial visibility into one business application. The cloud application is reached through app.akaunting.com. A self-hosted edition is also available. [1, 18, 19]</p><h3>How to read this guide</h3>'+table(['Pages','Contents'],[['3-4','Feature tree and the accounting workflow tree'],['5-7','Sales, purchases and bank transactions'],['8-9','Accounting records, cash/accrual and financial reports'],['10-12','Access, settings, optional apps and integrations'],['13-14','Worked example, operating checklist and terminology'],['15','Official source links']])+box('<strong>Availability labels:</strong> [F] documented platform function; inclusion and limits depend on edition/plan. [A] separate app or app-dependent capability. [E] illustrative example or recommended working practice, not a claim about a particular screen.')+'<h3>What is not assumed</h3><p>No claim is made that every feature is free, installed in your account or supported by every bank. Exact pricing, user limits and app bundles must be checked against the selected subscription. The pricing page could not be reliably retrieved during this review.</p>'+refs([1,18,19]))
page('02 / Feature tree', '<p class="caption">A conceptual map of the product, rather than a literal copy of its menu. [A] marks optional or app-dependent branches.</p><figure>'+feature+'</figure><p class="caption">Start with the business records; add specialist apps only when needed. Sources [1, 2, 9, 10, 16, 17].</p>')
page('03 / Accounting workflow tree','<p class="caption">Follow the transaction from setup to payment, verification and reporting. This diagram is an explanatory synthesis of the documented workflows.</p><figure>'+workflow+'</figure><p class="caption">An invoice or bill and its payment are related records. Creating one does not mean the other has happened. Sources [3-12]; controls in step 7 are recommendations [E].</p>')
page('04 / Sales: from invoice to receipt', '<h3>Customers and invoices [F]</h3><p>Create a customer, choose the invoice date and reference, then add products or services with descriptions, quantities and rates. Apply configured taxes and eligible line or overall discounts. Notes, categories and attachments provide context. Save and send the invoice through the available delivery options. [3]</p><h3>Receiving money [F]</h3><p>Record payment against the invoice using the actual receipt date, payment account and method. Payments can be full or partial. A remaining balance is still owed by the customer; an invoice should not be treated as fully settled merely because it was sent. [4]</p>'+table(['Record','Purpose','Example [E]'],[['Customer','Who is buying','Cedar Retail'],['Invoice','What they owe','Services: Rs 100,000'],['Payment / receipt','Money actually received','Rs 60,000 into bank'],['Outstanding balance','Amount still to collect','Rs 40,000']])+box('<strong>Practical check [E]:</strong> when a bank receipt already exists, connect it to the invoice rather than recording the same receipt twice.')+'<h3>Related capabilities</h3><p>The client portal exposes customer-facing records. Recurring documents support repeat billing. Estimates are a separate capability whose app/plan availability should be checked. [1, 17]</p>'+refs([3,4,1,17]))
page('05 / Purchases: bills and expenses', '<h3>Supplier bills [F]</h3><p>A bill records a supplier obligation. Choose the vendor and document date, enter the bill reference, add items, prices and applicable taxes or discounts, and attach supporting evidence. Categories and notes help explain the cost. [5]</p><h3>Payment versus obligation [F]</h3><p>Record the supplier payment against the bill, including the payment account, amount and date. Partial payments leave an unpaid balance. Direct expenses can instead represent spending that is recorded without a separate supplier bill. [6, 7]</p>'+table(['Situation','Record to consider','Control [E]'],[['Supplier allows payment later','Bill, followed by payment','Keep due date and unpaid amount visible'],['Expense paid immediately','Direct expense or paid bill','Do not record both for one cost'],['Part-payment to supplier','Payment against existing bill','Check the remaining balance'],['Regular rent or service charge','Recurring bill where available','Review amount before paying']])+'<h3>Worked example [E]</h3><p>A supplier bill is Rs 30,000. The business pays Rs 20,000 from its bank account. The payment reduces the amount owed to Rs 10,000. The bill total remains Rs 30,000; the payment is not another purchase.</p>'+refs([5,6,7]))
page('06 / Banking and money movements', '<h3>Accounts and transactions [F]</h3><p>Cash and bank accounts identify where money is held. Income and expense transactions record the date, method, account, amount, category and reference. Existing money movements may be connected to matching invoices or bills, including partial-payment situations. [1, 7]</p>'+table(['Movement','Plain-language meaning','Recording check [E]'],[['Income receipt','Money coming into an account','Identify the customer or reason'],['Expense payment','Money leaving an account','Identify the supplier or reason'],['Account transfer','Money moved between own accounts','Do not treat the transfer as a new sale'],['Opening balance','Money already held at the starting date','Verify against the migration cutoff']])+'<h3>Bank feeds [A]</h3><p>The Bank Feeds app can synchronize transactions from supported institutions. The official help page lists the US, Canada, Australia, New Zealand, UK and EU. Do not assume Pakistani bank connectivity; confirm the specific institution and current provider coverage. Manual transaction entry remains a separate workflow. [8]</p><h3>Reconciliation [E]</h3><p>Compare the bank statement with recorded money movements. Investigate duplicates, missing fees, wrong dates and incorrect amounts before relying on cash balances. A feed imports information; it does not remove the need for review.</p>'+refs([1,7,8]))
page('07 / The accounting layer', '<h3>Double-entry is a separate capability [A]</h3><p>The Chart of Accounts feature requires the Double-Entry app. Accounts can have a code, classification and parent account. The main classifications cover assets, liabilities, equity, income and expenses. The app adds ledger-oriented accounting, including journal and statement capabilities. [9, 10]</p>'+table(['Account family','What it represents','Illustrative account [E]'],[['Assets','Resources the business owns','Bank, customer receivables'],['Liabilities','Amounts the business owes','Supplier payables'],['Equity','Owner interest in the business','Owner capital'],['Income','Value earned by the business','Service revenue'],['Expenses','Costs incurred','Rent, office supplies']])+'<h3>Cash versus accrual [F]</h3><p>Akaunting documents accrual-based accounting and a cash option in reports. Accrual looks at when income is earned or costs are incurred; cash looks at receipt and payment timing. Results can differ even for the same period. Confirm the basis selected before comparing reports. [11]</p>'+box('<strong>Illustration [E]:</strong> invoice Rs 100,000; receipt Rs 60,000. Ignoring taxes and other adjustments, the earned amount and cash received are different. A debit/credit example appears on page 13.')+refs([9,10,11]))
page('08 / Reports: what each answers', '<p>Report names appear in the official catalogue, but their availability depends on the installed apps and plan. A catalogue entry alone does not mean it is included in the basic application. [12]</p>'+table(['Report / view','Question it answers','Availability note'],[['Income summary','Where did recorded income come from?','Documented reporting'],['Expense summary','Where are recorded costs concentrated?','Documented reporting'],['Income versus expense','How do the two totals compare?','Documented reporting'],['Tax summary','What tax amounts were recorded?','Configuration and report dependent'],['Customer statement','What activity belongs to this customer?','Check plan/report availability'],['Profit and loss','What is the accounting result for a period?','Check basis and accounting app'],['Balance sheet','What are assets, liabilities and equity?','Double-Entry related [A]'],['Trial balance','What are debit/credit balances by account?','Double-Entry related [A]'],['General ledger','What entries make up account balances?','Double-Entry related [A]'],['Cash flow statement','How did cash change across activities?','Check app/report availability']])+'<h3>Read reports consistently [E]</h3><p>Use the same company, reporting dates, currency treatment and cash/accrual basis. Trace an unexpected total back to its underlying records. A tax summary is not proof that a tax return has been filed or accepted.</p>'+refs([12,10,11]))
page('09 / Users, companies and access', '<p>Documented roles include Accountant, Customer, Employee and Manager, with Admin also listed for the self-hosted edition. The cloud and self-hosted role models are not identical. The help page states that on-premise role management requires the Roles &amp; Permissions app. [13]</p><h3>Recommended access design [E]</h3>'+table(['Person','Appropriate working scope','Avoid granting automatically'],[['Business owner','Oversight of permitted companies','Unrestricted access to unrelated entities'],['Accountant','Financial records and accounting reports','Infrastructure administration without need'],['Accounts operator','Prepare invoices, bills and receipts','Uncontrolled accounting adjustments'],['Manager','Relevant oversight and approved actions','Full access merely because of job title'],['Employee','Their permitted employee workflows','Whole-company financial information'],['Customer','Their own portal records','Other customers or internal records']])+'<h3>Company separation [F / E]</h3><p>Akaunting supports multiple businesses and company assignments. Treat company selection as a data boundary. Before rollout, test whether each role can view, create, edit, delete and export the intended records. The matrix above is a recommended policy, not a reproduction of Akaunting defaults.</p>'+refs([13,1]))
page('10 / Setup and configuration', '<h3>Business setup checklist [E]</h3>'+bullets(['Choose cloud or self-hosting and identify the accountable administrator.','Create the business profile and confirm the default currency and reporting dates.','Set invoice identity, numbering conventions and customer-facing text.','Add cash/bank accounts and agree opening balances at a single cutoff date.','Prepare customer, vendor and product/service lists.','Configure named tax rates and review how they apply to transactions.','Map categories; add ledger accounts if Double-Entry is installed.','Assign company access and permitted roles before inviting the wider team.'])+'<h3>Tax configuration [F]</h3><p>Akaunting documents creation and management of tax rates. Configure the intended rate and type before applying them to items or documents. Do not assume that choosing a tax label implements every local reporting or filing rule. [14]</p><h3>Products and services [F / A]</h3><p>Items provide reusable names, descriptions and prices for billing and purchasing. Stock quantities, warehouses and inventory operations belong to the Inventory app scope; a basic item list is not a full stock-control system. [15, 16]</p>'+box('<strong>Illustration only:</strong> all rupee amounts in this guide are examples. No statutory tax percentage, local filing integration or regulatory compliance has been assumed.')+refs([14,15,16,2]))
page('11 / Optional apps and deployment', '<p>Akaunting distinguishes native feature apps from third-party integrations. Installing or purchasing an app can extend the menus and workflow. These extensions should be scoped separately from everyday invoicing and bill entry. [17]</p>'+table(['App area [A]','Business purpose','What to verify'],[['Double-Entry','Accounts, journals and financial statements','Availability, account mappings and opening entries'],['Inventory','Warehouses, variants and stock operations','Quantity rules and accounting integration'],['Estimates / quotes','Proposals before invoicing','Conversion and document behaviour'],['Payroll / employees','Pay calendars and payslips','Country-specific suitability'],['Projects / CRM','Project work and customer pipeline','Overlap with existing business systems'],['Expense claims','Employee claim and approval workflows','Approval scope and payment handling'],['Payment integrations','Online collection','Provider coverage, fees and settlement'],['Bank Feeds','Bank transaction synchronization','Supported country and institution']])+'<h3>Cloud or self-hosted?</h3><p>Cloud uses Akaunting-hosted infrastructure; self-hosting places the application on infrastructure you operate. For self-hosting, plan for deployment, updates, restore testing and maintenance. Check the current subscription and app terms for either route rather than relying on broad free-software marketing. [18]</p>'+refs([17,16,10,8,18]))
page('12 / One complete accounting example', '<p class="caption">Illustrative double-entry explanation [E]. Assumes the Double-Entry capability, accrual accounting, no tax, one currency and no inventory.</p>'+table(['Event','Business record','Illustrative accounting effect'],[['1. Invoice customer Rs 100,000','Customer invoice','Debit receivables 100,000; credit revenue 100,000'],['2. Receive Rs 60,000','Payment linked to invoice','Debit bank 60,000; credit receivables 60,000'],['3. Supplier bill Rs 30,000','Expense bill','Debit expense 30,000; credit payables 30,000'],['4. Pay supplier Rs 20,000','Payment linked to bill','Debit payables 20,000; credit bank 20,000']])+'<h3>Result after these four events</h3>'+table(['Measure','Amount','Meaning'],[['Revenue earned','Rs 100,000','Does not mean all cash was received'],['Expense incurred','Rs 30,000','Does not mean all cash was paid'],['Illustrative profit','Rs 70,000','100,000 less 30,000'],['Net bank movement','Rs 40,000 increase','60,000 received less 20,000 paid'],['Customer balance','Rs 40,000 receivable','Still to collect'],['Supplier balance','Rs 10,000 payable','Still to pay']])+box('Profit and cash movement differ. The invoice, receipt, bill and payment each describe a different part of the same business activity. This example explains the concepts; it is not a guarantee of automatic posting under every configuration.')+refs([11,9,10]))
page('13 / Operating checklist and glossary', '<h3>Recommended routine [E]</h3>'+table(['When','Review'],[['Daily','Enter new documents; record receipts/payments; attach evidence; check overdue items.'],['Weekly','Match bank movements; resolve duplicate or unconnected records; review customer/supplier balances.'],['Monthly','Reconcile accounts; check cash/accrual basis; review statements and unusual postings; retain exports.'],['When access changes','Remove unnecessary company permissions and verify customer/employee isolation.'],['Before an app or major update','Confirm compatibility, test critical workflows and check the recovery plan.']])+'<h3>Plain-language glossary</h3>'+table(['Term','Meaning'],[['Invoice','Document requesting customer payment.'],['Bill','Supplier document recording what the business owes.'],['Receivable / payable','Amount to collect / amount to pay.'],['Payment account','The cash or bank account used for a money movement.'],['Category / ledger account','A business grouping / a formal accounting classification. They are not interchangeable.'],['Journal / ledger','Balanced accounting entry / history grouped by account.'],['Reconciliation','Comparing recorded activity with external evidence, usually a statement.'],['Accrual / cash basis','Recognition by earning/incurring / recognition by receiving/paying.']])+'<p class="caption">Concept definitions and routines are explanatory material, not a claim that every control has a dedicated Akaunting screen.</p>')
page('14 / Official sources', '<p>Public official pages reviewed on 20 October 2026. Use these links for current details. Plan inclusions, app availability and interface labels may change.</p><ol class="source-list">'+''.join('<li><strong>'+html.escape(title)+'</strong><br><a href="'+url+'">'+html.escape(url)+'</a></li>' for title,url in sources)+'</ol><p class="caption">Research boundary: no customer account login, installed-app inspection or paid-plan purchase was performed. The diagrams and worked example are original explanatory material.</p>')
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#e9ecf2;color:#253047;font-family:Arial,sans-serif;font-size:11.4pt;line-height:1.55}.page{width:210mm;height:297mm;padding:16mm 17mm 18mm;background:white;position:relative;break-after:page;overflow:hidden}.page:last-child{break-after:auto}.kicker{color:#6554cc;font-size:8.5pt;letter-spacing:1.6px;font-weight:bold;margin-bottom:12px}.topline{height:4px;background:linear-gradient(90deg,#6554cc,#168782);margin-bottom:24px;width:80px}h1{font-size:25pt;line-height:1.16;margin:0 0 22px;letter-spacing:-.7px}h3{font-size:13pt;margin:23px 0 9px;color:#323d58}p{margin:10px 0 15px}table{border-collapse:collapse;width:100%;font-size:9.7pt;margin:15px 0;line-height:1.45}th{text-align:left;color:white;background:#303850;padding:10px}td{padding:10px;border-bottom:1px solid #dfe4ef;vertical-align:top}tr:nth-child(even) td{background:#f6f7fb}td:first-child{font-weight:600}ul{padding-left:22px}li{margin-bottom:9px}.note{background:#f1effc;border-left:4px solid #6554cc;padding:15px 17px;font-size:10pt;margin:22px 0}.caption,.refs{font-size:9pt;color:#66738a;line-height:1.5}.refs{margin-top:24px;border-top:1px solid #e5e8ef;padding-top:10px}a{color:#5343b7;text-decoration:none;overflow-wrap:anywhere}.footer{position:absolute;bottom:9mm;left:17mm;right:17mm;border-top:1px solid #e0e4ed;padding-top:6px;display:flex;justify-content:space-between;font-size:8pt;color:#788398}.cover-title{font-size:34pt;line-height:1.15;font-weight:bold;margin:55px 0 24px;letter-spacing:-1px}.lead{font-size:17pt;color:#66738a;max-width:550px}.cover-tags{font-size:9pt;font-weight:bold;letter-spacing:.6px;color:#168782;margin-top:36px}.cover-bottom{margin-top:100px}.cover-bottom p{color:#66738a;font-size:11pt}figure{margin:0}figure svg{width:100%;height:202mm}.source-list{font-size:8.1pt;padding-left:20px;line-height:1.35}.source-list li{margin-bottom:8px}.source-list a{font-size:7.9pt}@media screen{.page{margin:20px auto;box-shadow:0 4px 24px #0001}}@media print{body{background:white}.page{margin:0}}'''
html_doc='<!doctype html><html><head><meta charset="utf-8"><title>Akaunting - Software and Accounting Workflow Guide</title><style>'+css+'</style></head><body>'+''.join('<section class="page"><div class="topline"></div><div class="kicker">'+p['kicker']+'</div><h1>'+p['title']+'</h1>'+p['body']+'<div class="footer"><span>JUDIBAS / AKAUNTING REFERENCE</span><span>'+str(i+1)+' / '+str(len(pages))+'</span></div></section>' for i,p in enumerate(pages))+'</body></html>'
(out/'Akaunting-Guide.html').write_text(html_doc,encoding='utf-8');(out/'guide-content.json').write_text(json.dumps(pages,ensure_ascii=False),encoding='utf-8')
print('Created guide source with',len(pages),'pages')
